using Swashbuckle.AspNetCore.Annotations;namespace GraphApi.Models.TKT.EstadosTickets{    [SwaggerSchema("Modelo de lectura de un EstadosTicket")]    [GraphQLDescription("Objeto que representa un EstadosTicket existente.")]    public class clReadEstadosTickets    {        [SwaggerSchema("Identificador único del EstadosTicket")]        [GraphQLDescription("Identificador único del EstadosTicket")]        public int? EstadoTicketID { get; set; }        [SwaggerSchema("EstadoTicket")]        [GraphQLDescription("EstadoTicket")]        public string? EstadoTicket { get; set; } = default!;        [SwaggerSchema("bEliminado")]        [GraphQLDescription("bEliminado")]        public bool? bEliminado { get; set; }    }    [SwaggerSchema("Modelo de creación de un EstadosTicket")]    [GraphQLDescription("Input para crear un EstadosTicket.")]    public class clCreateEstadosTickets    {        [GraphQLNonNullType] [SwaggerSchema("EstadoTicket")]        [GraphQLDescription("EstadoTicket")]        public string EstadoTicket { get; set; } = default!;        [GraphQLNonNullType] [SwaggerSchema("bEliminado")]        [GraphQLDescription("bEliminado")]        public bool bEliminado { get; set; }    }    [SwaggerSchema("Modelo de actualización de un EstadosTicket")]    [GraphQLDescription("Input para actualizar parcialmente un EstadosTicket.")]    public class clUpdateEstadosTickets    {        [SwaggerSchema("Identificador único del EstadosTicket")]        [GraphQLDescription("Identificador único del EstadosTicket")]        public int? EstadoTicketID { get; set; }        [SwaggerSchema("EstadoTicket")]        [GraphQLDescription("EstadoTicket")]        public string? EstadoTicket { get; set; }        [SwaggerSchema("bEliminado")]        [GraphQLDescription("bEliminado")]        public bool? bEliminado { get; set; }    }}